output_text:
[
  {
    "id": "no_cart_in_single_file_aisle",
    "text": "Shopping carts are not allowed in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_between_opposing_shelves",
    "text": "A cart must not be pushed through a narrow passage where shelves are directly on both sides.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "betweenOpposingShelves"
        ]
      }
    }
  },
  {
    "id": "wide_shelf_interactions_require_cart",
    "text": "Interactions with shelves from ordinary wide service aisles must be done while holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideShelfServiceCell": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "wideShelfServiceCell",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_pickups_are_cartless",
    "text": "Shelf interactions inside single-file aisles must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfSlot": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "singleFileShelfSlot",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "park_cart_before_narrow_aisle",
    "text": "Upon reaching the mouth of the single-file aisle with a cart, the agent is obliged to park the cart before entering.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        },
        "atMouthWithCart": {
          "and": [
            "narrowAisleMouth",
            "hasCart"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "atMouthWithCart",
      "discharge": "dropCart"
    }
  },
  {
    "id": "retrieve_cart_after_single_file_trip",
    "text": "After returning from a single-file aisle to the cart parking point, the agent must pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "narrowAisleMouth": "at(6,3)"
      },
      "events": {
        "returnFromSingleFileToMouth": {
          "pre": {
            "and": [
              "singleFileAisle",
              "S"
            ]
          },
          "post": "narrowAisleMouth"
        },
        "pickUpCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnFromSingleFileToMouth",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "do_not_leave_cart_mouth_without_cart",
    "text": "Once at the narrow-aisle mouth without a cart, the agent may only go into the narrow aisle or pick the cart up, not walk away into the wider store.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": "at(6,3)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "narrowAisleMouth",
          {
            "not": "hasCart"
          },
          {
            "or": [
              "S",
              "E",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "park_only_in_wide_clear_aisles",
    "text": "Carts may be parked only in wide clear aisle cells, not beside shelves or inside constrained passages.",
    "abstraction": {
      "state_properties": {
        "wideClearAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "wideClearAisle"
          }
        ]
      }
    }
  }
]
